const input=$json.body??$json;
const s=v=>String(v??'').trim();
const first=(...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const identity=input.identity??{};
const leadId=s(first(input.lead_id,identity.lead_id,input.packet?.identity?.lead_id));
const propertyId=s(first(input.property_id,identity.property_id,input.packet?.identity?.property_id));
const dealId=s(first(input.deal_id,identity.deal_id,input.packet?.identity?.deal_id));
const property=input.property??input.packet?.property??{};
const propertyType=s(first(input.property_type,property.type,input.packet?.property?.type)).toLowerCase();
const address=s(first(input.property_address,property.address,input.packet?.property?.address));
const id=s(first(dealId,propertyId,leadId));
const requestId=s(input.request_id)||('canonical-packet:'+(id||'unknown')+':v1');
const evidence=input.evidence??input.packet?.evidence??{};
const quality=input.evidence_quality??input.source_quality??input.packet?.evidence_quality??null;
const status=input.status??input.packet?.evidence_status?.complete;
const required=['valuation','comps','repairs','risk','buyer_demand','exit_strategy'];
const normalized={valuation:first(evidence.valuation,evidence.market_value,evidence.arv),comps:first(evidence.comps,evidence.comps_evidence),repairs:first(evidence.repairs,evidence.repair_evidence,evidence.estimated_repairs),risk:first(evidence.risk,evidence.property_risk,evidence.risk_evidence),buyer_demand:first(evidence.buyer_demand,evidence.buyer_demand_evidence),exit_strategy:first(evidence.exit_strategy,evidence.exit_evidence)};
const missing=required.filter(k=>normalized[k]===undefined||normalized[k]===null||normalized[k]==='');
const confidence=Number(quality?.overall_score??quality?.score??0);
const conflicts=Array.isArray(quality?.conflicts)?quality.conflicts:[];
const complete=missing.length===0&&conflicts.length===0&&status!=='evidence_incomplete';
const packetId=s(input.packet_id??input.packet?.packet_id)||('underwriting-packet:'+(id||'unknown')+':v2');
const packet={schema_version:'underwriting_packet.v2',packet_id:packetId,request_id:requestId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},property:{type:propertyType||null,address:address||null},evidence:normalized,evidence_quality:quality,evidence_status:{required,missing,complete,conflicts},policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true,land_specific_logic:propertyType.includes('land')||propertyType.includes('vacant')},source_metadata:{source_workflow:s(input.source_workflow)||'wf-113',normalized_at:new Date().toISOString()}};
return[{json:{ok:complete,status:complete?'canonical_packet_ready':conflicts.length?'canonical_packet_conflict':missing.length?'canonical_packet_incomplete':'canonical_packet_blocked',packet,missing_evidence:missing,confidence_score:confidence,next_workflow:complete?'wf-069-deal-viability-mao-strategy-gate':conflicts.length?'human_review':'wf-111-underwriting-evidence-reconciliation'}}];
